-- Add the Sandy club walkthrough and specialist Film Club and meeting media training.
-- Refresh original unedited drafts only. Authored drafts and released versions are preserved.

INSERT INTO learning_courses (id, category_id, site_id, provider_name)
VALUES ('sandy-how-it-works', 'site-tours', 'sandy-sports-training', 'Sandy Sports')
