INSERT INTO learning_course_versions (course_id, revision, state, title, description, lessons_json, practical)
VALUES ('sandy-how-it-works', 1, 'draft', 'How Sandy Sports works', 'A walkthrough of the public site, My Membership, the committee room and who does what. Follow a few everyday requests from the first click to the decision.', json('[
  {"title":"Three doors into the club","body":"Open How it works and start with the three doors. The public site explains the proposal and shows public news, sport and film information. My Membership is the signed-in place for your own profile, calendar, offers to help, Film Club, notices, family details and privacy choices. Officers enter the committee room to use the desks available to their office. Use the public map of the site to find a route before seeking new access. Sandy is in formation. An example event or preview desk can show the intended path while the club arranges permission and real delivery.","captureNotes":"Show the public three-door map on desktop and mobile. Use a synthetic account only if demonstrating the signed-in view. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html"},
  {"title":"Read the access table","body":"Find one responsibility in the access table and follow its row across the offices. Look at the difference between being able to open a desk, being able to change a record and being able to approve or send it. An officer may see a story in the news desk while a narrower office group can publish it. The page builds its table from the site''s access definitions. A committee resolution and the relevant governing documents are the route for an actual change of authority. During formation, check the draft constitution and confirm who can act on a specific task.","captureNotes":"Show the access table and the draft constitution Schedule 1 link. Point out the read and action columns without showing any real accounts. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html"},
  {"title":"From joining to taking part","body":"Follow Joining and the blue tick. A person starts with the public join route, sets their own profile and can then find the member welcome and participation steps. The access table and workflow show where an officer handles the welcome or sights ID in person. See how a volunteer offer, event RSVP and notification each have their own path. Check the family and safeguarding flow when a guardian is involved. Use the private family area for permissions and send any uncertain participation issue to the relevant safeguarding contact.","captureNotes":"Use the joining, event and safeguarding flow cards. Demonstrate with a fictional guardian and member account where available. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#processes"},
  {"title":"From an idea to a notice, event or story","body":"Follow three examples. An officer prepares an event run sheet and a member records an RSVP. A notice author selects an audience and checks who will receive it. A Film Club member sends an Island News story, the Sandy editor reviews it and a partner steward handles any network copy. Use the legend to spot where the site sends an update automatically and where a person has to act. The kit-loan example is a useful comparison because the owner decides and the site delivers the messages.","captureNotes":"Walk from a fictional beach sport event to its member notice and film story. Highlight the distinct actor labels in each flow. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"},
  {"title":"From committee decisions to ongoing work","body":"Open the meeting and AGM flow. Find who prepares the agenda, how the meeting becomes an approved record, and how follow-up tasks reach officers. Then check the officer access flow for a resolution, invitation and handover. Browse the newsletter, sponsorship and store examples to identify the human decision and the record it leaves. If a handoff stalls, follow the flow to the next actor and share the task reference through the appropriate channel.","captureNotes":"Show the flow from agenda to an action owner using one fictional decision. Include the officer access and newsletter links. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings"}
]'), '')
ON CONFLICT (course_id, revision) DO NOTHING;

