INSERT INTO learning_course_versions (course_id, revision, state, title, description, lessons_json, practical)
VALUES ('sandy-film-member', 1, 'draft', 'Sandy Film Club member guide', 'Pick a Film Club lane, find a first activity, borrow kit and find the right route to submit a story or join a sports crew.', json('[
  {"title":"Find your way into Film Club","body":"The public Film Club page explains the proposed screenings, filmmaking, sport coverage and workshops. If access is open to you, sign in to My Membership and open Film club. Join and choose the ways you want to take part. Watch is for screenings, Make is for creating stories, Sport crew is for game coverage and Learn is for workshops and practice. Your choices can change as you try things.","captureNotes":"Capture the public page and show the four lane cards in a synthetic My Membership account. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"},
  {"title":"Choose a first session","body":"For a screening, check its confirmed time, location, accessibility and the organiser''s instructions. To make something, ask what story the shoot is about, who is leading it and where the footage will go. To try sport crew or Learn, ask for a supervised task such as checking sound or logging shots. A phone and headphones can be enough for a first practice. Check event confirmation before travelling or bringing kit.","captureNotes":"Show four fictional activity cards and one example calendar handoff. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"},
  {"title":"Use the kit shelf","body":"Open Film club in My Membership to see available kit. If listing your own gear, decide whether it stays just yours, can be lent to members or only goes out with you. Send the kit owner your dates, intended use and any care questions. Wait for the owner’s answer, agree the collection privately and check the item together. Return it with accessories, report any damage and check that the return is marked.","captureNotes":"Capture the sharing choices, ask button and a fictional return. Keep addresses and contact details out of the capture. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-kit"},
  {"title":"Get permission and send a story","body":"Ask permission before capturing identifiable people for a specific use. Check the organiser’s and guardian arrangements for children and check separate cultural authority where relevant. In the Film club tab you can send an Island News headline, summary and details with optional public video and a chosen credit. Follow the reviewer’s response and use the contributor course if you want to report or film regularly.","captureNotes":"Show the story submission fields with a fictional public event and a sample credit. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"},
  {"title":"Join a sport crew or try a workshop","body":"Agree a small task, call time, point of contact and handoff with the crew lead. Ask what may be filmed and how to opt out, and where to deliver a labelled copy. A public broadcast needs a named crew and a separate publishing decision. After the activity, return kit, send permitted files to the lead and ask what to practise next.","captureNotes":"Walk through a fictional sport crew brief and show the link to Island News. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html"}
]'), '')
ON CONFLICT (course_id, revision) DO NOTHING;

