INSERT INTO learning_course_versions (course_id, revision, state, title, description, lessons_json, practical)
VALUES ('meeting-media-operator', 1, 'draft', 'Meeting recording, transcription and archives', 'Prepare and run an authorised closed or public meeting recording. Produce checked minutes and hand the correct files to the records custodian.', json('[
  {"title":"Agree the audience and assign the jobs","body":"Use the agenda to identify public, members-only and closed items. Ask the Chair to confirm the decision, purpose, audience and boundaries before capture starts. The Secretary should own the official meeting record and name the recorder and backup. The Assistant Secretary can operate the recorder when delegated. A public session also needs a producer or operator, a second viewer where available and an authorised publisher. Read permissions separately from the actual delegation. Agree who can order an immediate stop and who can resume.","captureNotes":"Show a fictional meeting brief and highlight the two separate roles of recorder and publisher. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"An officer can open the meeting desk but there is no recording decision. What should they do?","choices":[{"id":"a","text":"Treat signed-in access as the recording decision."},{"id":"b","text":"Ask the Chair to confirm authority and the Secretary to delegate the recorder."},{"id":"c","text":"Set a recording running and advise the Chair at the end."}],"correct_choice_id":"b","explanation":"Desk access shows who can use the site. Capture needs its own meeting authority and assigned operator.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Who should own the official minutes and recording record after a helper runs the equipment?","choices":[{"id":"a","text":"The equipment owner, because their computer created the file."},{"id":"b","text":"The external stream host, because it provided a replay."},{"id":"c","text":"The Secretary or formally designated records officer."}],"correct_choice_id":"c","explanation":"The designated officer controls the official record. Operation and hosting are separate jobs.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings"]}]},
  {"title":"Permission and the change to closed business","body":"Before capturing, explain what will be recorded, which service if any receives it, the audience, retention and how to raise objections. For a closed meeting, an explicit agreement from everyone affected and a record of it are the club practice taught here. Check rules and Queensland requirements before any wider use or disclosure. Reconfirm after a late arrival. Use manual minutes if permission or scope is uncertain. Stop the public stream and any public recording before a closed item. Confirm with the remote viewer and the room mic operator before speaking. A restricted recording needs its own approval.","captureNotes":"Rehearse the stop signal, cut public capture on all sources and check the remote viewing device reaches its end state. Reference: https://www.legislation.qld.gov.au/view/whole/html/inforce/2025-07-03/act-1971-050","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A late person joins a closed session that included consent to record. What now?","choices":[{"id":"a","text":"Pause capture, explain scope and check agreement before resuming."},{"id":"b","text":"Keep capturing while the Secretary explains consent over the recorded mic."},{"id":"c","text":"Wait until after the meeting and ask if the footage can be kept."}],"correct_choice_id":"a","explanation":"Pausing keeps the late arrival outside the recording until the agreed procedure is followed.","source_refs":["https://www.legislation.qld.gov.au/view/whole/html/inforce/2025-07-03/act-1971-050"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The Chair moves to closed business with the public viewer still hearing room sound. What happens next?","choices":[{"id":"a","text":"Add a closed-item label and let the replay editor remove it."},{"id":"b","text":"Hold discussion, stop the public output and check remote audio before proceeding."},{"id":"c","text":"Cover the camera and continue discussing the item."}],"correct_choice_id":"b","explanation":"Stopping and checking both sound and picture prevents a live disclosure.","source_refs":["https://www.legislation.qld.gov.au/view/whole/html/inforce/2025-07-03/act-1971-050"]}]},
  {"title":"Record in PLFC and Sandy","body":"In PLFC, use the meeting desk recording controls for approved microphone audio or camera plus audio. Select the right input and test playback using fictional material first. Its browser speech recognition may start during capture if supported, and the speech provider may process audio over the network. Explain that before using the combined consent control. In Sandy, the local browser recorder captures audio. Stop and download before navigating away, test the file, then transfer to the agreed restricted store. Have a named person take manual minutes during both workflows and whenever equipment, consent or internet fails.","captureNotes":"Show start, level check, stop and local download in each club using approved test data. Do not record a real meeting or an actual resident in a training capture. Reference: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"PLFC speech recognition is unavailable on the meeting laptop. What can still happen?","choices":[{"id":"a","text":"Restart repeatedly until a transcript appears before anyone speaks."},{"id":"b","text":"Upload the recording to whichever free speech tool recognises it."},{"id":"c","text":"Take manual minutes and separately confirm whether authorised audio capture should continue."}],"correct_choice_id":"c","explanation":"Minutes can proceed manually. The choice to send restricted audio somewhere else needs separate authority.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Sandy has stopped capture and the Secretary needs the file tomorrow. What should the recorder do now?","choices":[{"id":"a","text":"Download, verify playback and hand the file to the designated store before leaving the page."},{"id":"b","text":"Leave the browser window open and expect the meeting desk to keep the recording."},{"id":"c","text":"Drop the download into a public replay folder so others can find it."}],"correct_choice_id":"a","explanation":"Sandy’s recording route ends in a local download. Check the actual file and complete the restricted handoff.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]},
  {"title":"Transcribe, check and minute","body":"Use editable browser text where approved in PLFC. Sandy’s recorder downloads the audio and the Secretary can arrange a human or approved local transcription workflow if needed. Any external processing needs agreed handling for that material. A transcript captures what was said. Minutes capture attendance, decisions, motions, actions and any other records the rules require. Check names, numbers, motions, votes and dates against the source, flag unclear audio and let an authorised officer review. If using an optional AI minutes assistant, send only approved text through that club’s route and review every output.","captureNotes":"Use a fictional motion with a deliberate number recognition error. Compare source audio, transcript and a dedicated minutes draft. Reference: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Draft speech recognition says $1,500 and the motion seems to say $150. What should you do?","choices":[{"id":"a","text":"Use the sounding of the AI summary to settle the difference."},{"id":"b","text":"Check the timestamp and meeting record, ask the responsible officer if needed and leave it unresolved pending confirmation."},{"id":"c","text":"Pick the figure that fits the budget."}],"correct_choice_id":"b","explanation":"A transcript and a generated summary can both be wrong. Verify the exact motion and leave an audit trail.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A confidential recording needs a transcript and the browser provider has not been approved for that meeting. What is a proper next step?","choices":[{"id":"a","text":"Paste the entire recording into a personal AI account to save time."},{"id":"b","text":"Share a secret public link with an online caption provider."},{"id":"c","text":"Seek authorised human or approved offline transcription, or rely on manually checked minutes."}],"correct_choice_id":"c","explanation":"Keep the recording inside the agreed handling boundary while arranging an authorised transcription method.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]},
  {"title":"Prepare a public recording, stream and replay","body":"Use an approved channel and an encoder such as OBS Studio. Set a focused camera and clean mic feed, test levels and a backup recording, and have a remote viewer check the actual stream. Test privately first. Manage the stream in the hosting service. Sandy’s Island News desk controls its public listing, so separately start and stop the provider and check the site listing. Review permissions, edit any cuts, check captions and seek release approval before linking a replay. Agree a fallback to an approved recorded release when live streaming fails.","captureNotes":"Demonstrate a private OBS test and a Sandy listing using a sandbox or mock, including stopping the provider first and closing the listing. Reference: https://obsproject.com/kb/quick-start-guide","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Sandy says Live but a second device sees the channel waiting for video. Where is the first check?","choices":[{"id":"a","text":"Confirm the encoder and host are actually sending and receiving before updating the listing."},{"id":"b","text":"Refresh Sandy until it starts sending audio."},{"id":"c","text":"Create a second Island News story to start the same encoder."}],"correct_choice_id":"a","explanation":"The public bar points to the host. It does not send the audio or pictures.","source_refs":["https://obsproject.com/kb/quick-start-guide"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The host creates a replay immediately when a stream ends. What should the publisher do?","choices":[{"id":"a","text":"Replace official minutes with the automatically generated replay and transcript."},{"id":"b","text":"Check host visibility, hold replay release for review and add the approved version after checks."},{"id":"c","text":"Publish the host link straight away and review the footage afterwards."}],"correct_choice_id":"b","explanation":"A replay is a separate release. Check permissions, privacy and the approved version before linking it.","source_refs":["https://obsproject.com/kb/quick-start-guide"]}]},
  {"title":"Archive approved minutes, restricted masters and public copies","body":"Use the meeting reference, date, custodian, scope, permission, approval, access and disposition to index each artefact. File approved minutes and related actions in the official records system. Keep restricted source files, working transcripts and excluded segments in an access-controlled club store with an assigned custodian and checked backups. Store approved public replay and captions as a separate edition with a release history and working public URL. Use the club''s agreed retention schedule, keep anything under a hold and log authorised disposal or withdrawal, including how backups expire.","captureNotes":"Demonstrate an archive index, restore check and approved deletion entry using synthetic files and paths only. Reference: https://support.google.com/youtube/answer/6247592","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A committee member asks for the public stream and private raw master in the same share folder. What should you do?","choices":[{"id":"a","text":"Give all committee accounts automatic access to every recording."},{"id":"b","text":"Put both in the public folder with different file names."},{"id":"c","text":"Use separate access-controlled records and share only the version that is authorised for each recipient."}],"correct_choice_id":"c","explanation":"The permission follows the artefact and audience. Distinct storage reduces accidental disclosure.","source_refs":["https://support.google.com/youtube/answer/6247592"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The archive schedule says a raw file is due for disposal but it has a current records hold. What should you do?","choices":[{"id":"a","text":"Keep it restricted, note the hold and review it once the responsible officer clears it."},{"id":"b","text":"Delete it from the main drive and rely on the host replay."},{"id":"c","text":"Change the file''s label to public so the schedule no longer applies."}],"correct_choice_id":"a","explanation":"A hold suspends the planned disposal. Track review and disposal only after clearance.","source_refs":["https://support.google.com/youtube/answer/6247592"]}]}
]'), 'In a synthetic meeting, submit a chair-approved recording plan, an access and consent log, a checked sample transcript and draft minutes, and two archive entries (restricted and public). Demonstrate that the person watching the public feed cannot hear the closed item. The assessor checks scope, the stop signal, accuracy, access and disposition.')
ON CONFLICT (course_id, revision) DO NOTHING;

