INSERT INTO learning_course_versions (course_id, revision, state, title, description, lessons_json, practical)
VALUES ('sandy-island-news-contributor', 1, 'draft', 'Island News contributor', 'Plan, capture and file an accurate local Island News story with permission, useful captions and a clear handoff.', json('[
  {"title":"Find a reportable local story","body":"Choose a useful local event, game, place activity or community story. Note what happened, who is affected, what people can do next and what needs verification. Get time and place from the organiser and confirm changes against a second appropriate source. Write contributors and source links in your private notes. Ask a reviewer where to take an urgent safeguarding matter rather than putting it in a public pitch.","captureNotes":"Build a story card from two fictional club sources. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Two flyers have different dates for the same event. Which date should you use?","choices":[{"id":"a","text":"Copy both dates as if they are separate sessions."},{"id":"b","text":"Ask the organiser to confirm the authoritative date and timestamp the check."},{"id":"c","text":"Take the date from whichever flyer looks newer."}],"correct_choice_id":"b","explanation":"Resolve the conflicting dates with the organiser before filing.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Someone shares an unverified claim about an identifiable resident. How should you handle it?","choices":[{"id":"a","text":"Publish the claim in a question headline."},{"id":"b","text":"Include it in captions and ask viewers to decide."},{"id":"c","text":"Keep it out of the story and refer it privately if it raises a concern."}],"correct_choice_id":"c","explanation":"An accusation calls for verification and possibly a private reporting channel, rather than amplification.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]}]},
  {"title":"Plan permission, credits and boundaries","body":"Before filming, say what the coverage is for, where it may appear and whether stills, streaming or replay are planned. Record permission or the chosen approach to avoid identification. Check guardian arrangements and the event lead’s rules about children. For cultural content ask the appropriate custodians about recording, permitted audiences and reuse. Original media, music, logos and photographs have their own rights. Agree credits and keep a private evidence trail for the editor.","captureNotes":"Show a fictional release log and a permission boundary on a shot list. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"You have approval to take a still for internal club use. Can you add the person to an Island News reel?","choices":[{"id":"a","text":"Seek permission for that public use or choose a different shot."},{"id":"b","text":"Yes, because the original still permission covers any format."},{"id":"c","text":"Yes, if the edit crops some of the face."}],"correct_choice_id":"a","explanation":"Internal use and public publication are different scopes. Seek the appropriate permission.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Event permission is confirmed but a cultural performance has no recorded filming decision. What do you capture?","choices":[{"id":"a","text":"Ask the first audience member for authority to livestream it."},{"id":"b","text":"Capture cleared activity and check with the relevant custodian before filming the performance."},{"id":"c","text":"Record the whole programme and leave this for the public editor."}],"correct_choice_id":"b","explanation":"Event access and cultural authority are different. Check the specific footage with its custodian.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]}]},
  {"title":"Film and edit for the audience","body":"Use the lead''s safe filming places and shot boundaries. Capture a wide establishing shot, useful details, stable interviews and clean sound. Note the source for on-screen claims and confirm spellings. Edit a short coherent version and check its captions and credits. Look for children, medical incidents, name tags, screen messages or other unintended identifiers in the frame or audio. Keep original rushes under the agreed control.","captureNotes":"Show a fictional shot sequence, an audio test and caption correction. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A clear interview has a member contact list visible behind the speaker. What should you use?","choices":[{"id":"a","text":"Use it because the interviewee approved the interview."},{"id":"b","text":"Leave it visible and mention the problem in an email after publication."},{"id":"c","text":"Retake or make a reviewed edit that fully removes the list."}],"correct_choice_id":"c","explanation":"Permission for the interview does not cover private information in the background.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The caption tool misses a local name and alters a score. What is the next step?","choices":[{"id":"a","text":"Check with the source and correct the captions and any matching graphics."},{"id":"b","text":"Keep the autogenerated captions to show they are machine-made."},{"id":"c","text":"Delete all captions and submit the inaccurate graphic."}],"correct_choice_id":"a","explanation":"Captions and graphics need the same fact-checking as the spoken story.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]}]},
  {"title":"Fill the Film Club story form","body":"Sign in to My Membership and open Film club. Use a headline that tells readers what happened, a short summary and optional longer details. Check place, date and any public HTTPS video link. Choose club credit or a permitted first-name credit. Tick the publication permission check after checking the actual material. For any permission the editor needs to see, use the agreed private handoff. Reopen the member view to check the submission state.","captureNotes":"Capture submission with fake date, place, credit and an approved demo URL. Keep real member details out of frame. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The video link points to an unreviewed cut. What should you attach?","choices":[{"id":"a","text":"Use a private raw file link so it will automatically become public."},{"id":"b","text":"Use the approved cut or omit the optional link until the cut is cleared."},{"id":"c","text":"Use the link and rely on the editor to notice the filename."}],"correct_choice_id":"b","explanation":"The optional link should reference the cleared artefact intended for the audience.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"What does a submitted story mean?","choices":[{"id":"a","text":"The story appears immediately on Island News."},{"id":"b","text":"The Noticeboard partner already approved a copy."},{"id":"c","text":"The story is queued for human review."}],"correct_choice_id":"c","explanation":"Submission enters Sandy''s review process. Publication and any partner decisions happen later.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]}]},
  {"title":"Deal with updates and corrections","body":"Read feedback in the member account. Respond with the corrected claim or file reference and explain what changed. If permission changes or the video becomes unsafe, request withdrawal or alert the editor immediately. Check what is already published and let the editor coordinate correction on Sandy and any network copy. Keep a short source note so the reviewer can reproduce the check.","captureNotes":"Capture a fictional story feedback message and update. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A person withdraws permission while a story is still pending. What should you do?","choices":[{"id":"a","text":"Withdraw the pending item through the member flow or contact the editor immediately."},{"id":"b","text":"Wait for publication so readers can judge whether the person is identifiable."},{"id":"c","text":"Replace the media link after review without telling the editor."}],"correct_choice_id":"a","explanation":"The reviewer needs the withdrawal promptly and should review any replacement on its own merits.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A correction affects both Sandy and an exported network copy. Who should know?","choices":[{"id":"a","text":"Only the video hosting service."},{"id":"b","text":"The Sandy editor and the receiving network steward through the agreed handoff."},{"id":"c","text":"Only the original subject."}],"correct_choice_id":"b","explanation":"Tell the people who control every affected copy and preserve the correction reference.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]}]},
  {"title":"Hand over the source files","body":"Give the editor the approved publication file, rights and source references, a contact for corrections and any hold or pending check. Label version, contributor credit and intended audience. Transfer originals only through the agreed restricted channel when needed. Keep your written rundown short enough for someone else to take over tomorrow. Check that a story listed as published links to the reviewed edition.","captureNotes":"Create a sample handover manifest with source notes, media version and decisions. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Which file should an editor queue for the public version?","choices":[{"id":"a","text":"The oldest raw capture with no permissions record."},{"id":"b","text":"The highest-resolution item regardless of its editorial status."},{"id":"c","text":"The labelled, checked publication cut with its approval scope."}],"correct_choice_id":"c","explanation":"The public artefact needs its own known version and scope.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Your preferred credit and correction contact differ. Where do they go?","choices":[{"id":"a","text":"Use approved public credit and keep the correction contact in the restricted handoff."},{"id":"b","text":"Add both to the public headline."},{"id":"c","text":"Remove all private contact options so corrections have no route."}],"correct_choice_id":"a","explanation":"Keep a useful private correction channel and share only the agreed public credit.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]}]}
]'), 'Submit a fictional Island News pitch, rights and consent log, short captioned draft or shot plan, and filled example submission. After reviewer feedback, show a correction and source check. The reviewer checks accuracy, permissions, source credibility and usability.')
ON CONFLICT (course_id, revision) DO NOTHING;

