INSERT INTO learning_course_versions (course_id, revision, state, title, description, lessons_json, practical)
VALUES ('sandy-island-news-editor', 1, 'draft', 'Island News editor and publisher', 'Work the Island News queue, review evidence, make an accountable release decision and keep Sandy and partner copies current.', json('[
  {"title":"Open the queue and know your publishing authority","body":"Go to Committee room, Island news and live. Review items submitted from My Membership. Sandy’s officers can see the queue. The member records office group can act on stories and broadcasts: President or Vice President, Secretary or Assistant Secretary, Treasurer and Webmaster under the site''s current rules. Check your real editorial delegation too, along with conflicts of interest and availability of an alternate. For cases outside your remit, note the deadline and hand the reference to the agreed officer.","captureNotes":"Show the desk followed by the corresponding access row with fictional records. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A general committee officer sees a story with Publish unavailable. What should they do?","choices":[{"id":"a","text":"Make a public copy of the queue item in a personal account."},{"id":"b","text":"Send the story reference to an authorised editor and flag the deadline."},{"id":"c","text":"Borrow an authorised officer’s password to release it."}],"correct_choice_id":"b","explanation":"Visibility lets the officer coordinate. The decision belongs to someone who can act under the current delegation and permissions.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"You are the editor and the story promotes your own business. How can it proceed?","choices":[{"id":"a","text":"Approve it before declaring the interest at the next meeting."},{"id":"b","text":"Ask the contributor to remove your name but decide it yourself."},{"id":"c","text":"Declare the interest and hand the independent editorial decision to an appropriate alternate."}],"correct_choice_id":"c","explanation":"Disclosure and an independent reviewer protect the decision and the record.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]}]},
  {"title":"Verify use, context and source","body":"Check facts, date, place, spellings and what the linked video actually shows. Obtain an agreed source for significant public claims. Check permission for featured people, children and cultural material, plus copyright, audio, images and reuse terms. Verify the exact edition and where it can be published. Keep unnecessary personal details out of the editorial note. If a required fact or permission is missing, hold publication and tell the maker what would resolve it.","captureNotes":"Review a fictional story with a mismatched date and an incomplete public video permission. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A video switches from a cleared interview to unapproved identifiable footage. What decision fits?","choices":[{"id":"a","text":"Hold the release and ask for a cleared cut or appropriate permission."},{"id":"b","text":"Approve because the thumbnail image was cleared."},{"id":"c","text":"Change the headline and approve the same video."}],"correct_choice_id":"a","explanation":"The editor reviews the whole artefact for the channel, not just the text and preview.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Where should an editor record why a publication right is missing?","choices":[{"id":"a","text":"Only in a notification to a third party with no link to the story."},{"id":"b","text":"Restricted editorial notes with the relevant source reference."},{"id":"c","text":"The public summary, together with private contact details."}],"correct_choice_id":"b","explanation":"Restricted notes support later review without publishing unnecessary data.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]}]},
  {"title":"Publish, decline or correct in Sandy","body":"Edit title and summary for accuracy and accessibility. Check contributor credit, media link, public view and captions on a second device when possible. Use the desk to publish or decline with a clear review note. Keep the response actionable and suitable for the author to read. For a material change, check the new edition with the author and allowed reviewer. Confirm the released item appears as intended and that the contributor can find the decision.","captureNotes":"Show a mock publish and a decline note that points to an evidence gap. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"An editor changes a headline in a way that reverses the apparent meaning. What should happen before release?","choices":[{"id":"a","text":"Publish now because headlines are only an editing choice."},{"id":"b","text":"Only alter the contributor’s credit so the headline seems neutral."},{"id":"c","text":"Recheck the changed claim and approve the changed edition with the proper evidence."}],"correct_choice_id":"c","explanation":"A materially changed headline changes the approved public claim.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The public view shows an unexpected video after publication. What should you do?","choices":[{"id":"a","text":"Take down or hold the link, check the version and record the decision before restoring it."},{"id":"b","text":"Leave it up while sending a general feedback request."},{"id":"c","text":"Switch to another link without checking its permission."}],"correct_choice_id":"a","explanation":"Contain the incorrect release first and restore only a reviewed edition.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]}]},
  {"title":"Make an editorial handoff to the Screen Media Network","body":"Export the reviewed story from Sandy’s desk with its source, publication date, credit, on-site link and any reviewed video. Put the permission scope, correction contact and any reuse limits in the agreed handoff to the Minjerribah Screen Media Network steward. Ask for an acceptance or change request. Where the receiving publisher posts to a separate channel, log its public reference and who owns correction there.","captureNotes":"Export an example story and pair it with a mock steward review. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Sandy can publish a video on its own site and the release is silent about syndication. What do you send?","choices":[{"id":"a","text":"Treat the Markdown export as universal publication approval."},{"id":"b","text":"Refer the approved Sandy page or seek permission before supplying a copy for republication."},{"id":"c","text":"Export the raw footage with a note asking the network to take responsibility."}],"correct_choice_id":"b","explanation":"Permission for one outlet may have limits. The export is a handoff, with a separate partner check.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"How can Sandy tell whether a partner copy has gone live?","choices":[{"id":"a","text":"Assume the export button published to every screen."},{"id":"b","text":"Check only whether the Sandy copy is still visible."},{"id":"c","text":"Verify the partner’s acceptance and public reference and record both."}],"correct_choice_id":"c","explanation":"The receiving steward controls the next publication step.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-story"]}]},
  {"title":"Prepare a broadcast listing and approve its replay","body":"Set the confirmed Brisbane start time, place, audience and public stream link. Keep the running crew notes private. Coordinate with the producer on their private rehearsal, verified start, closed item boundaries and fallback. Use the status controls to reflect what the host is actually doing. After a permitted broadcast, add the checked replay link only when the reviewed version and captions are ready. A noticeboard copy needs the correct start and expiry plus an identified receiving steward.","captureNotes":"Show the schedule, Live and End controls beside a mock producer checklist. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"What should go in the public scheduled stream field?","choices":[{"id":"a","text":"The public viewing URL verified from a separate device."},{"id":"b","text":"The encoder stream key so the partner can publish too."},{"id":"c","text":"A private organiser edit link."}],"correct_choice_id":"a","explanation":"The viewer URL is designed to be public. Stream keys and admin links remain private.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A planned start changes after the noticeboard receives an export. What happens?","choices":[{"id":"a","text":"Publish a new listing without stopping or correcting the earlier one."},{"id":"b","text":"Update Sandy, send the correction to the receiving steward and verify what viewers see."},{"id":"c","text":"Edit only the private crew note."}],"correct_choice_id":"b","explanation":"Control time-sensitive copies across both portals so viewers see the confirmed time.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]}]},
  {"title":"Correct, unpublish and hand over","body":"If an item has wrong information or unsafe content, check its immediate exposure and unpublish where needed. Preserve a private decision trail with version, actor, time and reason. Coordinate a correction or withdrawal with any steward and media host. Recheck whether an old replay, link or cached copy still displays. At shift end, hand over scheduled items, decisions due, open rights checks and emergency contacts for the actual publication channels.","captureNotes":"Run a simulated withdrawal and create a shift handoff with the affected locations. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/news.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A story is removed from Sandy but the linked replay remains public at the provider. What should you do?","choices":[{"id":"a","text":"Assume unpublishing Sandy also removes the external replay."},{"id":"b","text":"Restore the Sandy story so both channels match."},{"id":"c","text":"Contact the channel operator, check access there and follow up with any partner steward."}],"correct_choice_id":"c","explanation":"A linked publication has separate controls on each service.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"What does a constructive outgoing editor handoff contain?","choices":[{"id":"a","text":"Active and scheduled records, unresolved risks, decisions and the next responsible officer."},{"id":"b","text":"One file with shared passwords and raw submissions."},{"id":"c","text":"Only last month’s public headlines."}],"correct_choice_id":"a","explanation":"A safe handoff keeps responsibility and actionable references clear.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/news.html"]}]}
]'), 'In a simulated news desk, triage two stories, review their rights and source evidence, publish one mock release and return the other with reasons. Hand off a reviewed export and demonstrate a correction or withdrawal across a second fictional channel.')
ON CONFLICT (course_id, revision) DO NOTHING;

INSERT INTO learning_courses (id, category_id, site_id, provider_name)
