INSERT INTO learning_course_versions (course_id, revision, state, title, description, lessons_json, practical)
VALUES ('sandy-live-broadcast-crew', 1, 'draft', 'Sandy live broadcast crew', 'Run a supervised public sport, programme or meeting stream from a checked run sheet through to a reviewed replay and crew handover.', json('[
  {"title":"Build the run sheet and crew roster","body":"Agree the event’s authority and filming scope. Name the producer, camera and audio operators, authorised Sandy publisher and outside-feed checker. Small crews may combine jobs when responsibilities stay clear. List crew calls, internet access, inputs, camera limits, stream host, expected end, closed segments, child-safety arrangements, emergency stop and backup plan. Agree the site and noticeboard wording with the editor and keep access credentials in approved tools.","captureNotes":"Show a run sheet with public start, closed item boundaries and contacts represented by role titles. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Which role checks that the outgoing sound is actually reaching a viewer?","choices":[{"id":"a","text":"The room announcer listening to the PA."},{"id":"b","text":"The assigned outside-feed checker using the actual viewing URL."},{"id":"c","text":"The camera operator looking only at their viewfinder."}],"correct_choice_id":"b","explanation":"A check at the viewer end catches sound problems that occur after room and encoder mixing.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The crew has authority to film part of a session. Where does the stop point belong?","choices":[{"id":"a","text":"Only in the post-production editor''s notes."},{"id":"b","text":"In the public chat once the restricted segment has started."},{"id":"c","text":"On the run sheet and in the crew’s verbal rehearsal with an immediate stop signal."}],"correct_choice_id":"c","explanation":"The stop must be known and practised before going live.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]}]},
  {"title":"Wire picture and sound and rehearse privately","body":"Connect a camera or approved capture feed and the designated microphone input. Listen on headphones and test for clipping, echo, lag, feedback and accidental duplicate audio. Use a neutral holding scene with audio muted or intentionally routed. Set the approved hosting account in OBS or another encoder. Protect stream keys. Test the network and local recording at the venue using a private test stream, then check video, sound and captions from a separate viewer device.","captureNotes":"Capture a synthetic OBS test showing live meter, safe scene and second-device view. Mask accounts and keys. Reference: https://obsproject.com/kb/quick-start-guide","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A muted microphone is still audible in the stream preview. What should you check?","choices":[{"id":"a","text":"Check all input and desktop or monitoring routes, then confirm silence at the external player."},{"id":"b","text":"Turn off only the camera and resume practice."},{"id":"c","text":"Trust the mute icon without repeating the check."}],"correct_choice_id":"a","explanation":"Room sound can travel through other sources. Check every source the viewer can hear.","source_refs":["https://obsproject.com/kb/quick-start-guide"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Where does an encoder stream key go?","choices":[{"id":"a","text":"On a laminated sign next to the screen operated by volunteers."},{"id":"b","text":"In authorised encoder or protected credential storage."},{"id":"c","text":"In the public Sandy link field."}],"correct_choice_id":"b","explanation":"The stream key grants authority over the external channel.","source_refs":["https://obsproject.com/kb/quick-start-guide"]}]},
  {"title":"Go live in the host and link the public feed","body":"Bring the encoder up to the agreed service, check preview and start at the producer’s cue. Have the outside viewer confirm the correct picture and sound. Ask the Sandy editor to set the matching listing to Live and check the site takes viewers to the correct link. If a steward received a Noticeboard handoff, confirm the current schedule and the channel it will use. Keep a short live log of start, audio checks and change decisions.","captureNotes":"Show the external encoder, viewer and corresponding mock Sandy Live now listing. Reference: https://support.google.com/youtube/answer/2907883","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Which step makes the footage travel to viewers?","choices":[{"id":"a","text":"Saving a Sandy calendar entry."},{"id":"b","text":"Exporting the Noticeboard scheduling record."},{"id":"c","text":"The properly configured encoder and hosting service send it."}],"correct_choice_id":"c","explanation":"Sandy publicises the external broadcast link. The host and encoder carry the media.","source_refs":["https://support.google.com/youtube/answer/2907883"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The outside viewer hears unsynchronised audio while the room sounds fine. What should the crew do?","choices":[{"id":"a","text":"Use the fallback or hold scene while diagnosing the outgoing mix and retest externally."},{"id":"b","text":"Leave it because people in the room can hear."},{"id":"c","text":"Increase room PA level so the external timing catches up."}],"correct_choice_id":"a","explanation":"Broadcast input and network paths need a separate check.","source_refs":["https://support.google.com/youtube/answer/2907883"]}]},
  {"title":"Stop for privacy, incidents or technical failure","body":"Respond to the producer or chair’s stop signal. Before closed business, end the public feed and any public recording, then confirm silence and loss of picture externally. If a safeguarding or private incident enters shot, cut the public output and alert the producer. For a technical issue within the agreed scope, use the rehearsed holding scene or end the feed. Track a fallback such as recording authorised public material for release later. Give the editor the confirmed status or cancellation update.","captureNotes":"Rehearse a privacy stop and sustained network failure using simulation. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A child enters the background from an area marked no filming. What is the immediate priority?","choices":[{"id":"a","text":"Ask chat viewers to ignore the shot while leaving it live."},{"id":"b","text":"Cut or redirect the feed safely, confirm the output and tell the producer."},{"id":"c","text":"Wait until there is an editor available to blur the replay."}],"correct_choice_id":"b","explanation":"Contain live exposure first, then follow the agreed reporting and review procedure.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The signal has failed. What is a defensible recovery?","choices":[{"id":"a","text":"Start broadcasting the room from a personal account without checking permissions."},{"id":"b","text":"Leave the listing Live while the crew packs up."},{"id":"c","text":"Follow the run sheet, record only what remains authorised and tell the publisher which public status to set."}],"correct_choice_id":"c","explanation":"The fallback still needs the same authority and a truthful public update.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]}]},
  {"title":"End and check the replay before release","body":"Stop in the host or encoder as the service requires. Confirm the public output ended using a separate viewer, then tell the publisher to end the listing and close out any public notices. Stop and verify the local recording. Review provider replay visibility and any unintended cuts, captions, credits and rights. Check junior or closed material was excluded. Deliver the approved public copy to the editor with the rights record, or record a clear hold reason.","captureNotes":"Capture end confirmation and mock replay preview, captions and release check. Reference: https://support.google.com/youtube/answer/6247592","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The host link works and points to an unreviewed automatic replay. What should happen?","choices":[{"id":"a","text":"Restrict it where possible and hand the editor a replay hold pending review."},{"id":"b","text":"Add it to Sandy immediately because it plays from a phone."},{"id":"c","text":"Make it the official minutes to simplify archiving."}],"correct_choice_id":"a","explanation":"Provider archiving and public replay approval are distinct steps.","source_refs":["https://support.google.com/youtube/answer/6247592"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"How do you confirm the broadcast has actually ended?","choices":[{"id":"a","text":"Close your OBS window and leave without asking anyone."},{"id":"b","text":"Check the provider state and outside viewer, then check the Sandy listing."},{"id":"c","text":"Look only for the missing red bar on Sandy."}],"correct_choice_id":"b","explanation":"The host and the Sandy listing must both reflect what happened.","source_refs":["https://support.google.com/youtube/answer/6247592"]}]},
  {"title":"Return gear and transfer records","body":"Clean and return borrowed items with accessories and fault notes. Send the producer a timing log, incident notes, permission boundaries, checked file locations and release state. Put the full approved source in the agreed restricted store and give only the cleared output to the authorised publisher. Escalate a lost device or uncertain audience exposure promptly. Use a short debrief to assign repairs, captions and the next test to named people.","captureNotes":"Show a fictional kit return, a file manifest and a crew debrief with action owners. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-kit","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The local backup shows a closed discussion after the live feed ended. What should happen?","choices":[{"id":"a","text":"Deliver it directly to the public editor as an approved master."},{"id":"b","text":"Put it on a shared public drive so someone can remove the discussion later."},{"id":"c","text":"Restrict and report the file and review disposition before any replay edit or sharing."}],"correct_choice_id":"c","explanation":"End of a stream does not prove that every local recording stopped. Treat the source as restricted.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-kit"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The borrowed microphone fails on return. What records and handoff are needed?","choices":[{"id":"a","text":"Tell the owner and crew lead, record the fault and agree the next action."},{"id":"b","text":"Mark it good and let the next crew discover it."},{"id":"c","text":"Discard it without contacting the owner."}],"correct_choice_id":"a","explanation":"The loan and equipment log should accurately record condition and responsibility.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-kit"]}]}
]'), 'Use synthetic material to run a private encoder test, hand a sample listing to an authorised editor, switch to a safe scene, demonstrate immediate stop and verify the external feed ended. Produce a backup file check, corrected captions and a replay release or hold recommendation.')
ON CONFLICT (course_id, revision) DO NOTHING;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[2]', json('{"title":"Chair, declare interests and confirm outcomes","body":"Open with attendance and quorum and ask about interests before the relevant items. When an interest is disclosed, check the applicable process, record it and have the Secretary confirm what happens to participation and quorum. Keep discussion to the motion. Ask for the final wording and voting outcome to be read back. If authority or quorum fails, record the issue and use the rules for deferral or adjournment. Agree the action owner and due date before moving on.\n\nKeep the final motion, outcome, declaration handling, quorum and action owner in the authorised record.\n\nBefore capture, confirm the meeting''s authority, audience and consent plan with the Secretary. Signal the stop before a closed item and hold discussion until public picture and sound are off. If a private recording is proposed, approve its scope separately. Name who can resume. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through #committee/meetings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings Include the final motion, outcome, declaration handling, quorum and action owner using invented details. Show the PLFC meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A declaration leaves the meeting short of quorum for a motion. What should the chair do?","choices":[{"id":"a","text":"Use a show of hands from those remaining and ask the next meeting to ratify it."},{"id":"b","text":"Pause that decision, record the quorum issue and follow the rules for the next step."}],"correct_choice_id":"b","explanation":"The operating record needs the final motion, outcome, declaration handling, quorum and action owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the final motion, outcome, declaration handling, quorum and action owner"},{"id":"b","text":"the initial motion and a note the room generally agreed"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]}]}')),
  edit_version=edit_version+1
WHERE course_id='plfc-president' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[0]', json('{"title":"Agree delegation and chair cover","body":"Read the confirmed appointment and current rules with the President and Secretary. Agree what you will lead or follow up, what is reserved for the President or committee and how somebody records cover if circumstances change. Before leading a meeting check its type, notice, quorum, conflicts and chairing procedure. If you cannot verify your authority, ask the Secretary to record the issue and arrange the next step.\n\nKeep the cover, limits, meeting basis and decisions still needing referral in the authorised record.\n\nIf deputising as Chair, check the recording plan with the Secretary. Know who runs the recording, who checks the outside feed and who can stop it before closed business. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the cover, limits, meeting basis and decisions still needing referral using invented details. Show the PLFC meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The President is absent and an extra motion requires authority outside the cover agreement. How do you proceed?","choices":[{"id":"a","text":"Use the verified rules and seek the appropriate decision route before acting on the extra motion."},{"id":"b","text":"Treat taking the chair as full authority to decide on the extra business."}],"correct_choice_id":"a","explanation":"The operating record needs the cover, limits, meeting basis and decisions still needing referral. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the calendar invitation and the absent officer’s title"},{"id":"b","text":"the cover, limits, meeting basis and decisions still needing referral"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')),
  edit_version=edit_version+1
WHERE course_id='plfc-vice-president' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[2]', json('{"title":"Minute decisions, then release the right version","body":"During the meeting, record attendance, quorum, disclosures and handling, actual motions, amendments, vote outcomes and action owners. If recording is proposed, seek the required consent and agree custody and retention. Treat speech transcription and AI suggestions as working material, use the separate approval for any AI processing and verify wording against participants and the meeting record. Track draft, approved and released states separately. Publish the authorised member edition and keep originals and sensitive material private.\n\nKeep the approved minute, separate member edition, consent records and action source in the authorised record.\n\nOwn the approved record and delegate a named recorder and backup. The PLFC desk provides consent-gated audio or camera and audio with a local download. Its optional browser transcription may use a speech provider. Verify the resulting text, keep signed-off minutes separately and index the restricted recording in the agreed archive. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through #committee/meetings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings Include the approved minute, separate member edition, consent records and action source using invented details. Show the PLFC meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A transcript suggestion changes who is responsible for an action. What belongs in the approved minutes?","choices":[{"id":"a","text":"The allocation confirmed by the actual meeting, after checking with the chair or decision source."},{"id":"b","text":"The suggested allocation because it appears in the draft transcript."}],"correct_choice_id":"a","explanation":"The operating record needs the approved minute, separate member edition, consent records and action source. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a text transcript with a publish flag and no verification"},{"id":"b","text":"the approved minute, separate member edition, consent records and action source"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]}]}')),
  edit_version=edit_version+1
WHERE course_id='plfc-secretary' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[2]', json('{"title":"Record decisions and close follow-up actions","body":"Compare approved decisions with the officer lists. Put each action on the right office’s list with a due date and source. Print individual lists on club letterhead when used. Check returned sheets with the officer where the marks or dates are unclear, then record completion or reopen the correct item. Do not publish working notes or transcript suggestions as minutes. Keep owner and completion evidence with the original decision.\n\nKeep the motion reference, assigned officer, due date and evidence for the part completed in the authorised record.\n\nWhen delegated to record, confirm the Chair’s agreement and explain PLFC’s capture and transcription options. Test the selected input, stop on the Chair’s cue, download and play back before leaving, then hand the restricted file to the Secretary. Take backup notes and verify transcript details before drafting minutes. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through #committee/todo with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo Include the motion reference, assigned officer, due date and evidence for the part completed using invented details. Show the PLFC meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A paper sheet marks a job done but the payment approval it depends on is still open. What do you record?","choices":[{"id":"a","text":"Mark the whole action complete and leave the decision source unlinked."},{"id":"b","text":"Confirm the scope of what was done and leave the approval dependency open with a named follow-up."}],"correct_choice_id":"b","explanation":"The operating record needs the motion reference, assigned officer, due date and evidence for the part completed. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the motion reference, assigned officer, due date and evidence for the part completed"},{"id":"b","text":"a tick against the job without the unresolved dependency"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo"]}]}')),
  edit_version=edit_version+1
WHERE course_id='plfc-assistant-secretary' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[1]', json('{"title":"Prepare meetings and handle conflicts","body":"Agree the purpose, notice, papers, eligible participants and current status of each item with the Secretary. Chair a fictional meeting using the relevant adopted or proposed rules explicitly for its status. Record interests, how participation changes, quorum and the outcome of each item. If the authority or rule is unclear, record the reason to defer. Ask the Secretary to read back the agreed wording, owners and deadlines. Separate decisions on planning from future formal votes.\n\nKeep the meeting basis, disclosures, wording and action owner, with draft or formal status in the authorised record.\n\nAgree the agenda’s broadcast scope with the Secretary and use a named Film Club producer for an approved public feed. At the change to closed business, stop public output and local public capture and wait for the crew''s confirmation. Authorise any restricted capture or public replay separately. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the meeting basis, disclosures, wording and action owner, with draft or formal status using invented details. Show the Sandy meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A group discusses a proposed rule and appears to agree informally. How do you record it?","choices":[{"id":"a","text":"Record the discussion and any agreed planning action, and identify the proper process for adopting rules."},{"id":"b","text":"Mark the rule adopted because none of the people present objected."}],"correct_choice_id":"a","explanation":"The operating record needs the meeting basis, disclosures, wording and action owner, with draft or formal status. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a list of ideas labelled resolutions by the chair"},{"id":"b","text":"the meeting basis, disclosures, wording and action owner, with draft or formal status"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')),
  edit_version=edit_version+1
WHERE course_id='sandy-president' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[0]', json('{"title":"Agree deputy cover and access","body":"Check the prospective role status and what authority has actually been recorded. Agree when you would cover the Chair and which decisions you can facilitate, recommend or refer. Read the actual meeting basis, agenda and possible conflicts before acting. Use your own approved access and check which member or safeguarded records your role can open.\n\nKeep the cover and role status, permitted actions and decision owners in the authorised record.\n\nWhen covering as Chair, confirm who can record, publish and retain each part of the meeting. Agree the start and stop signals and require the independent viewer to confirm silence before closed business. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the cover and role status, permitted actions and decision owners using invented details. Show the Sandy meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The Chair asks you to run a discussion but a commitment is proposed during it. What do you check?","choices":[{"id":"a","text":"Check the scope of your cover and take the commitment through the current authorised decision process."},{"id":"b","text":"Assume the cover includes authority for every item discussed."}],"correct_choice_id":"a","explanation":"The operating record needs the cover and role status, permitted actions and decision owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a calendar invitation with no delegation"},{"id":"b","text":"the cover and role status, permitted actions and decision owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')),
  edit_version=edit_version+1
WHERE course_id='sandy-vice-president' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[2]', json('{"title":"Minute decisions and preserve the approval trail","body":"Keep attendance, quorum where applicable, interest declarations, actual wording, outcomes and follow-up owners in the appropriate record. Label transcript or AI-assisted text as draft and check it against the actual discussion. Clear any use of recordings or processing with the responsible people. Reconcile the final minutes with officer tasks. Use version and history to preserve what was amended, reviewed and released to the right audience.\n\nKeep the corrected draft, actual decision, approval version and resulting actions in the authorised record.\n\nAgree who takes minutes, who records and who holds the archive. Sandy’s meeting recorder downloads local audio. Arrange approved transcription separately, check motions and figures, and submit the appropriate minutes for review. Keep restricted raw files away from public media links and give any redacted member edition its own approval. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the corrected draft, actual decision, approval version and resulting actions using invented details. Show the Sandy meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A generated minute says the club approved a spend when it only discussed an estimate. What do you record?","choices":[{"id":"a","text":"Accept the draft because the figure and item are otherwise correct."},{"id":"b","text":"Correct the minutes against what happened and retain the decision or proposal status and reviewer."}],"correct_choice_id":"b","explanation":"The operating record needs the corrected draft, actual decision, approval version and resulting actions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the corrected draft, actual decision, approval version and resulting actions"},{"id":"b","text":"a polished AI summary with no check against the source"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')),
  edit_version=edit_version+1
WHERE course_id='sandy-secretary' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[1]', json('{"title":"Prepare meeting papers and support the record","body":"Check papers, draft agenda, circulated versions, relevant notices and nominations with the Secretary. Flag a missing report or changed motion while it is still useful to reschedule or correct. In approved cover, record the actual outcome, attendance and actions and route sensitive working notes appropriately. Review any transcript suggestions against what was agreed before the next version is shared.\n\nKeep the agenda and notice versions, source papers, decision and update owner in the authorised record.\n\nWhen delegated to operate Sandy’s audio recorder, check and record agreement, do a short playback test, stop and download before leaving the page, and transfer the verified file privately to the Secretary. Take manual notes and correct any separately approved transcript before draft minutes go to review. For a full rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the agenda and notice versions, source papers, decision and update owner using invented details. Show the Sandy meeting desk with fictional data. Rehearse the stop signal or private file handoff. https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-meetings","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You find an amended agenda after members received the notice. What do you do first?","choices":[{"id":"a","text":"Confirm what was sent and which authorised correction or next process applies."},{"id":"b","text":"Put the amended version on the public calendar so everyone sees the latest file."}],"correct_choice_id":"a","explanation":"The operating record needs the agenda and notice versions, source papers, decision and update owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"an overwritten attachment with no record of recipients"},{"id":"b","text":"the agenda and notice versions, source papers, decision and update owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')),
  edit_version=edit_version+1
WHERE course_id='sandy-assistant-secretary' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json, '$[0]', json('{"title":"Choose how you want to take part","body":"Explore the film club and proposed screenings. Ask whether a session is for an audience, a workshop crew or people learning a particular task.\n\nIf you have member access, open My Membership, then Film club. Choose Watch, Make, Sport crew or Learn. The same tab contains kit and Island News routes. See Sandy Film Club member guide for borrowing equipment or sending a story and use Island News to find any approved public videos and live links.","captureNotes":"Show a public film club concept and fictional workshop listing. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/ Show My Membership, Film club and Island News from a synthetic view. https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"}')),
  edit_version=edit_version+1
WHERE course_id='sandy-film-participant' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json('[
  {"title":"Scope the film activity and authorise the next step","body":"Describe the audience and aim and choose whether it is a screening, workshop or production. Agree the deliverable, likely space, gear, crew, cost and responsible leads. Identify which permissions, funding and date decisions are still needed. Keep the project listed at the status actually agreed and coordinate with sports, facilities and partners before promising capacity.\n\nKeep the event scope, people, budget assumptions and open authority in the authorised record.","captureNotes":"Walk through Film club and media programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the event scope, people, budget assumptions and open authority using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The team has a venue concept and a popular film in mind. What does the lead record?","choices":[{"id":"a","text":"A proposed format and pending venue, rights, budget and crew decisions."},{"id":"b","text":"A planned public screening ready to advertise while checks continue."}],"correct_choice_id":"a","explanation":"The operating record needs the event scope, people, budget assumptions and open authority. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a film title and draft event graphic"},{"id":"b","text":"the event scope, people, budget assumptions and open authority"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]},
  {"title":"Check screening rights, recording permissions and credits","body":"Identify who can approve the film or other material for the proposed audience, platform and use. Separate permission to screen, capture, edit, use music, distribute and share a participant’s image. Check any child or cultural material with the appropriate authorised people. Log credits, scope, restrictions and clearance and brief the crew on what they can use. Hold any unconfirmed items for review.\n\nKeep the permission and use register, responsible decision-makers and holds in the authorised record.","captureNotes":"Walk through Film club and media programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the permission and use register, responsible decision-makers and holds using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A filmmaker gives permission for one venue screening and someone wants to post the cut online. What is needed?","choices":[{"id":"a","text":"Use the screening approval because the video file and credits are unchanged."},{"id":"b","text":"Confirm the extra scope with the relevant rights holders and record it before release."}],"correct_choice_id":"b","explanation":"The operating record needs the permission and use register, responsible decision-makers and holds. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the permission and use register, responsible decision-makers and holds"},{"id":"b","text":"a single cleared check covering every possible use"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]},
  {"title":"Coordinate people, venue and the run of show","body":"Agree the venue conditions, capacity, access instructions, opening and closing, audience welcome, accessible viewing and who controls changes. Assign sound, projection, registration and pack-down to people who can cover the schedule. Check permissions and safeguarding arrangements with the relevant lead. Agree the setup and handover times, backup for a missing role and who can pause a programme.\n\nKeep the venue conditions, cue sheet, owners, backups and stop contact in the authorised record.","captureNotes":"Walk through Venue, court and screen bookings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the venue conditions, cue sheet, owners, backups and stop contact using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One person is assigned to welcome and projection during doors open. What should the lead do?","choices":[{"id":"a","text":"Reassign or stagger duties and test that the critical jobs have coverage."},{"id":"b","text":"Keep the roles together and trust the crew member will move quickly."}],"correct_choice_id":"a","explanation":"The operating record needs the venue conditions, cue sheet, owners, backups and stop contact. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a guest schedule with no crew assignments"},{"id":"b","text":"the venue conditions, cue sheet, owners, backups and stop contact"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]},
  {"title":"Test production, captions and playback","body":"Before welcoming people, check the actual file and version, visible pictures, sound level, captions and audience sightlines. For a workshop test the equipment, supervision, permitted shots and transfer path. Agree safe gear handling and route an equipment or power issue through the responsible qualified person where required. Rehearse an alternative or pause if sound, projector, weather or accessibility changes. Record which test passed and who repeats it.\n\nKeep the checked version, observed playback, equipment exceptions and readiness decision in the authorised record.","captureNotes":"Walk through Film club and media programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the checked version, observed playback, equipment exceptions and readiness decision using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The file opens on a laptop but the actual show has unreadable captions on the venue screen. What must happen?","choices":[{"id":"a","text":"Keep the checked laptop file and assume it will be readable from most seats."},{"id":"b","text":"Adjust or replace the file and verify captions on the actual equipment before calling it ready."}],"correct_choice_id":"b","explanation":"The operating record needs the checked version, observed playback, equipment exceptions and readiness decision. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the checked version, observed playback, equipment exceptions and readiness decision"},{"id":"b","text":"a record that the film file downloaded successfully"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]},
  {"title":"Control expenses, sponsors and event comms","body":"Confirm quotes, hire and condition records, cancellation terms, approved spending and custody with the Treasurer and facilities lead. Check what contributors have agreed about credits and sponsor acknowledgement. Ask the responsible officers to approve and verify public messaging. Use one authorised update after a changed time or venue and record which channels were checked.\n\nKeep the approved hire or loan, wording, release channels and changes in the authorised record.","captureNotes":"Walk through Sport, film and community events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the approved hire or loan, wording, release channels and changes using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supporter provides gear and requests a new public credit just before release. What do you do?","choices":[{"id":"a","text":"Check the exact terms and approved wording before changing the release."},{"id":"b","text":"Add the wider acknowledgement to every channel because gear was lent."}],"correct_choice_id":"a","explanation":"The operating record needs the approved hire or loan, wording, release channels and changes. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"purchase estimates and a logo without actual permission"},{"id":"b","text":"the approved hire or loan, wording, release channels and changes"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]},
  {"title":"Close screenings or production and hand over","body":"Check the actual deliverable, return and condition of gear, authorised files and backups, rights and retention, incident or complaint route, costs, attendance and feedback. Log which final export was approved and which copy belonged to the rehearsal. Give the next lead the source versions, partner and venue commitments, outstanding rights or claims and review date.\n\nKeep the final version, gear custody, rights, costs and unresolved action references in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the final version, gear custody, rights, costs and unresolved action references using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The final folder contains a rough cut and a reviewed cut. What does the successor need?","choices":[{"id":"a","text":"Send the newest export and rely on the file date to indicate approval."},{"id":"b","text":"Identify the reviewed version and its use conditions, plus any outstanding changes and owner."}],"correct_choice_id":"b","explanation":"The operating record needs the final version, gear custody, rights, costs and unresolved action references. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the final version, gear custody, rights, costs and unresolved action references"},{"id":"b","text":"an archive with loose exports and no status"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]},
  {"title":"Run the Film Club lanes and kit shelf","body":"Plan a balance of Watch, Make, Sport crew and Learn activities. Give each a confirmed lead, suitable venue and safe scope. Use My Membership to guide existing members into Film Club and explain where to change lanes. For the kit shelf, retain owner choice, agreed dates, care notes and controlled collection. Confirm actual condition on return and route faults or late returns to the lead. Maintain a brief covering inductions, safeguarding, availability, access and the next person responsible.","captureNotes":"Demonstrate each lane, a supervised crew introduction and a closed fictional kit loan. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"An item is listed only when the owner comes along. A second crew wants to collect it alone. What do you arrange?","choices":[{"id":"a","text":"Share the owner''s address so the crew can ask in person."},{"id":"b","text":"Agree a session with the owner or choose another suitable item."},{"id":"c","text":"Mark the owner’s item as generally lendable."}],"correct_choice_id":"b","explanation":"The owner chooses the sharing scope and controls any collection arrangements.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Who plans supervision and permission for a new member filming the junior match?","choices":[{"id":"a","text":"The member can assume it from choosing Sport crew."},{"id":"b","text":"The editor checks after the member streams the match."},{"id":"c","text":"The Film Club lead with the event and safeguarding leads, before capture."}],"correct_choice_id":"c","explanation":"Plan supervision and capture boundaries before junior participation.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/film-club.html"]}]},
  {"title":"Connect production to Island News and live coverage","body":"Send Island News stories through the Film Club member form. Pair each with the approved capture scope, contributor credit and sources. The authorised Sandy editor makes the publication decision and can hand an appropriate copy to the Screen Media Network steward. For broadcasts, assign a producer, technical crew and filmmaker permissions, and name the separate Sandy publisher. Agree start, public and closed boundaries, stop signal, replay review and what the Straddie Noticeboard receives. Rehearse and check the external stream ends as planned.","captureNotes":"Build a fictional production sheet connecting the crew, news queue, broadcast listing and network steward. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The Film Club producer and camera operator are ready, but there is no signed-in editor authorised to manage the news listing. What next?","choices":[{"id":"a","text":"Arrange an authorised publisher and agree the release plan before going publicly live."},{"id":"b","text":"Ask the camera operator to use the editor’s account."},{"id":"c","text":"Publish it on an unrelated personal channel and notify the club later."}],"correct_choice_id":"a","explanation":"The producer runs capture and makes sure the editor is available for the distinct publishing decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A network steward requests a wider reuse of footage cleared for Sandy only. What is the appropriate handoff?","choices":[{"id":"a","text":"Re-label the footage as jointly owned and send the replay."},{"id":"b","text":"Get the wider permission or agree a limited reference to the Sandy public page."},{"id":"c","text":"Send the source footage since the steward can decide any rights later."}],"correct_choice_id":"b","explanation":"The original permission scope travels with the media. Any wider reuse needs appropriate authority.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]}]}
]'),
  practical='Build a fictional screening or film workshop pack. Include format and scope, venue and screening or participant permissions, a cue sheet and roster, sound and caption checks, approvals for one paid or hired item, a plan for a failure or weather change, and release and gear handover. Pass when the duty owners can set up and pause the event, all intended uses have reviewed authority, and any open permission or equipment issue is easy to find. Include a lane and kit-loan plan and show who is authorised to release a story or list, stop and review a live broadcast. The assessor should check the Screen Media Network handoff and the replay permission boundary.',
  edit_version=edit_version+1
WHERE course_id='sandy-film-lead' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;
